def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in ``[start, finish]`` ending in ``s``.

    Every decimal digit in a counted integer must be at most ``limit``.
    The count is computed by counting valid suffix-matching integers up to
    each endpoint, so it also works for ranges too large to enumerate.
    """
    if start > finish or finish < 1 or not s:
        return 0
    if not (1 <= limit <= 9):
        raise ValueError("limit must be between 1 and 9")
    if any(ch < "0" or ch > "9" for ch in s):
        raise ValueError("s must contain only decimal digits")
    if any(int(ch) > limit for ch in s):
        return 0

    suffix_len = len(s)

    def count_up_to(bound: int) -> int:
        """Count eligible positive integers no greater than bound."""
        if bound < 1:
            return 0
        bound_text = str(bound)
        bound_len = len(bound_text)
        if bound_len < suffix_len:
            return 0

        total = 0

        # All shorter lengths are unrestricted by the bound. The prefix is
        # empty when the number is exactly the length of the fixed suffix.
        for length in range(suffix_len, bound_len):
            prefix_len = length - suffix_len
            if prefix_len == 0:
                total += 1
            else:
                # The first prefix digit cannot be zero.
                if limit >= 1:
                    total += limit * (limit + 1) ** (prefix_len - 1)

        # For equal-length values, compare the variable prefix to the bound's
        # prefix. Any smaller valid prefix qualifies regardless of suffix;
        # an equal prefix qualifies only when s is no greater than the bound's
        # remaining suffix.
        prefix_len = bound_len - suffix_len
        bound_prefix = bound_text[:prefix_len]
        bound_suffix = bound_text[prefix_len:]

        if prefix_len == 0:
            return total + (1 if s <= bound_text else 0)

        ways_after = [1] * (prefix_len + 1)
        for pos in range(prefix_len - 1, -1, -1):
            choices = limit if pos == 0 else limit + 1
            ways_after[pos] = choices * ways_after[pos + 1]

        for pos, char in enumerate(bound_prefix):
            bound_digit = ord(char) - ord("0")
            min_digit = 1 if pos == 0 else 0
            smaller_choices = max(0, min(bound_digit, limit + 1) - min_digit)
            total += smaller_choices * ways_after[pos + 1]

            if bound_digit < min_digit or bound_digit > limit:
                break
        else:
            if s <= bound_suffix:
                total += 1

        return total

    return count_up_to(finish) - count_up_to(start - 1)
